import java.util.*;class SnakeGame{int w,h,score;int[][]food;Deque<Integer>b=new ArrayDeque<>();Set<Integer>s=new HashSet<>();public SnakeGame(int width,int height,int[][]food){w=width;h=height;this.food=food;b.addFirst(0);s.add(0);}public int move(String d){int p=b.peekFirst(),r=p/w,c=p%w;if(d.equals("U"))r--;else if(d.equals("D"))r++;else if(d.equals("L"))c--;else c++;if(r<0||c<0||r>=h||c>=w)return-1;int id=r*w+c;boolean eat=score<food.length&&food[score][0]==r&&food[score][1]==c;if(!eat)s.remove(b.removeLast());if(s.contains(id))return-1;b.addFirst(id);s.add(id);if(eat)score++;return score;}}
